const $=id=>document.getElementById(id);
const escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={scenario:'valmiki',page:'command',selected:'VTR-026',time:12,playing:false,speed:1,mode:'3d',layers:{fire:true,assets:true,routes:true,wind:true,context:true},progress:{},logs:[],missions:[],tour:-1,filter:'',typeFilter:'all'};
let terrain=null,timer=null,toastTimer=null;
try{const saved=JSON.parse(localStorage.getItem('abhai-firedome-demo-v1'));if(saved&&Array.isArray(saved.logs)&&Array.isArray(saved.missions)){state.progress=saved.progress||{};state.logs=saved.logs;state.missions=saved.missions}}catch{}
const scene=()=>SCENARIOS[state.scenario];
const incident=()=>scene().incidents.find(x=>x.id===state.selected)||scene().incidents[0];
const stage=()=>state.progress[incident().id]||0;
const clock=t=>{const minutes=Math.floor(t*.6);return String(14+Math.floor(minutes/60))+':'+String(minutes%60).padStart(2,'0')};
const realClock=()=>new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Kolkata'});
function save(){try{localStorage.setItem('abhai-firedome-demo-v1',JSON.stringify({progress:state.progress,logs:state.logs,missions:state.missions}))}catch{}}
function log(action){state.logs.unshift({id:incident().id,scenario:state.scenario,action,time:realClock(),kind:'Demo action'});save()}
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),4000)}
function pause(){state.playing=false;clearInterval(timer);timer=null;const b=$('playButton');if(b){b.textContent='▶';b.setAttribute('aria-label','Play scenario replay')}}
function changeScenario(key){if(!SCENARIOS[key])return;pause();state.scenario=key;state.selected=scene().incidents[0].id;state.time=12;state.filter='';render()}
function navigate(page){if(!NAV_ITEMS.some(x=>x[0]===page))return;pause();state.page=page;state.filter='';state.typeFilter='all';history.replaceState(null,'','#'+page);render()}
function render(){pause();if(terrain){terrain.destroy();terrain=null}renderNav();renderHeader();const views={command:renderCommand,streams:renderStreams,fleet:renderFleet,missions:renderMissions,zones:renderZones,history:renderHistory,safety:renderSafety,architecture:renderArchitecture};views[state.page]();renderTour();if(state.page==='architecture'){const link=document.createElement('a');link.href='/prototype/assets/ABHAI_FireDome_Technical_Kit.zip';link.download='ABHAI_FireDome_Technical_Kit.zip';link.className='button primary';link.style.display='inline-block';link.textContent='Download prototype source kit ↓';$('content').appendChild(link)}}
function renderNav(){$('navigation').innerHTML=NAV_ITEMS.map(([key,label,ico])=>`<button class="nav-item ${state.page===key?'active':''}" data-page="${key}" title="${label}" ${state.page===key?'aria-current="page"':''}>${icon(ico)}<span>${label}</span>${key==='missions'&&state.missions.length?`<span class="nav-count">${state.missions.length}</span>`:''}</button>`).join('');$('navigation').querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page))}
function renderHeader(){const info={command:['Command centre','Every signal. One operational picture.','From an early observation to a coordinated response.'],streams:['Stream manager','Evidence before action.','Review the recorded Mumbai demonstration and proposed pilot inputs.'],fleet:['Fleet','Know what is ready.','Aircraft, readiness and mission roles in the selected demonstration.'],missions:['Missions','From verification to response.','Human-approved reconnaissance, with an accountable decision trail.'],zones:['Zone search','Focus the next observation.','Configure a demonstration patrol zone and review its mission constraints.'],history:['Detection history','An incident has a memory.','Review scenario observations and actions performed in this prototype.'],safety:['Rules & safety','Human authority, at every critical step.','Review the proposed operating controls and demonstration boundaries.'],architecture:['CTO / architecture','One platform. Clear integration boundaries.','A concrete implementation conversation, grounded in the Mumbai application.']}[state.page];$('pageCrumb').textContent=info[0];$('pageTitle').textContent=info[1];$('pageDescription').textContent=info[2];$('scenarioTabs').innerHTML=Object.entries(SCENARIOS).map(([key,s])=>`<button class="scenario-tab ${state.scenario===key?'active':''}" data-scenario="${key}" ${state.scenario===key?'aria-pressed="true"':'aria-pressed="false"'}>${s.name}<small>${s.code==='MUM'?'RECORDED':'SIMULATED'}</small></button>`).join('');$('scenarioTabs').querySelectorAll('button').forEach(b=>b.onclick=()=>changeScenario(b.dataset.scenario));$('scenarioNote').textContent=scene().status;}
function stats(){const s=scene(),m=s.code==='MUM';return `<div class="stats"><div class="stat"><div class="stat-head">${m?'Evidence source':'Signals in this scenario'}${icon('fire')}</div><div class="stat-value">${m?'01':String(s.incidents.length).padStart(2,'0')}<span>${m?'recording':'observations'}</span></div><div class="stat-foot">${m?'User-supplied Mumbai application demo':'Simulated signals · not live detections'}</div></div><div class="stat"><div class="stat-head">${m?'Aircraft reference':'Surveillance readiness'}${icon('drone')}</div><div class="stat-value">${m?'01':s.assets}<span>${m?'named in UI':'available'}</span></div><div class="stat-foot">${m?'Current connection status unknown':'Illustrative fleet · not actual deployment'}</div></div><div class="stat"><div class="stat-head">Scenario wind${icon('wind')}</div><div class="stat-value">${s.wind}<span>${m?'not available':'km/h'}</span></div><div class="stat-foot">${m?'No weather inferred from video':s.windDirection+' · illustrative condition'}</div></div><div class="stat"><div class="stat-head">Selected incident${icon('shield')}</div><div class="stat-value" style="font-size:23px">${m?'Recorded':['Detected','Review','Verified','Requested','Responding','Closed'][stage()]}</div><div class="stat-foot">${m?'Review original evidence below':'Human authorisation · demo workflow'}</div></div></div>`}
function mapMarkup(zone=false){return `<section class="map-panel"><div class="panel-head"><div><h3>${zone?'Patrol zone preview':'Operational scene'}</h3><p>${scene().code==='MUM'?'Proposed visual overlay / recorded source':'Illustrative geography / scenario observations'}</p></div><div class="segment" aria-label="Map dimension"><button data-mode="2d" class="${state.mode==='2d'?'active':''}">2D</button><button data-mode="3d" class="${state.mode==='3d'?'active':''}">3D terrain</button></div></div><div class="map-stage"><canvas id="terrainCanvas" role="img" aria-label="Interactive illustrative ${scene().name} scene. Drag to rotate; select incidents using the observation list below."></canvas><div class="map-label"><div class="eyebrow">${scene().tag}</div><h3>${scene().location}</h3><p>Drag to rotate · scroll to zoom</p></div><div class="map-tools"><button id="zoomIn" aria-label="Zoom in">+</button><button id="zoomOut" aria-label="Zoom out">−</button><button id="resetCamera" aria-label="Reset map camera">⌖</button><div class="map-compass">N<br>↑</div></div><div class="map-legend"><span><i style="background:#edac72"></i>Scenario signal</span><span><i style="background:#a2d2d5"></i>Aircraft</span><span><i style="background:#a4bba0"></i>Context</span></div><div class="map-notice">ILLUSTRATIVE SCENE · NOT SURVEY DATA · NO LIVE CONNECTION</div><span class="signal-tag" id="sceneTime">${clock(state.time)} / REPLAY</span></div><div class="layers-row">${[['fire','Signals'],['assets','Aircraft'],['routes','Routes'],['wind','Wind'],['context',scene().terrain==='urban'?'Buildings':'Terrain context']].map(([k,label])=>`<label class="layer-toggle"><input type="checkbox" data-layer="${k}" ${state.layers[k]?'checked':''}>${label}</label>`).join('')}</div>${zone?'':`<div class="timeline"><div class="timeline-heading"><b id="replayMilestone">${scene().milestones[Math.min(5,Math.floor(state.time/20))]}</b><div class="timeline-controls"><span>Scenario replay</span><select id="speed" aria-label="Replay speed"><option value="1" ${state.speed===1?'selected':''}>1×</option><option value="2" ${state.speed===2?'selected':''}>2×</option><option value="4" ${state.speed===4?'selected':''}>4×</option></select></div></div><div class="timeline-bar"><button id="playButton" class="play" aria-label="Play scenario replay">▶</button><input id="replaySlider" aria-label="Scenario timeline" type="range" min="0" max="100" value="${state.time}"></div><div class="time-labels"><span>14:00</span><span>14:15</span><span>14:30</span><span>14:45</span><span>15:00</span></div></div>`}</section>`}
function attachMap(){terrain=new TerrainView($('terrainCanvas'),{scenario:scene(),selected:state.selected,onSelect:id=>{state.selected=id;render()}});terrain.mode=state.mode;terrain.time=state.time;terrain.layers={...state.layers};terrain.draw();document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{state.mode=b.dataset.mode;terrain.mode=state.mode;terrain.draw();document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('active',x.dataset.mode===state.mode))});document.querySelectorAll('[data-layer]').forEach(input=>input.onchange=()=>{state.layers[input.dataset.layer]=input.checked;terrain.layers={...state.layers};terrain.draw()});$('zoomIn').onclick=()=>{terrain.zoom=Math.min(1.8,terrain.zoom+.15);terrain.draw()};$('zoomOut').onclick=()=>{terrain.zoom=Math.max(.65,terrain.zoom-.15);terrain.draw()};$('resetCamera').onclick=()=>{terrain.angle=-.53;terrain.zoom=1;terrain.draw()};if($('replaySlider')){$('replaySlider').oninput=e=>{pause();setTime(+e.target.value)};$('speed').onchange=e=>state.speed=+e.target.value;$('playButton').onclick=togglePlayback}}
function setTime(t){state.time=Math.min(100,Math.max(0,t));if(terrain){terrain.time=state.time;terrain.draw()}if($('replaySlider'))$('replaySlider').value=state.time;if($('sceneTime'))$('sceneTime').textContent=clock(state.time)+' / REPLAY';if($('replayMilestone'))$('replayMilestone').textContent=scene().milestones[Math.min(5,Math.floor(state.time/20))]}
function togglePlayback(){if(state.playing){pause();return}if(state.time>=100)setTime(0);state.playing=true;$('playButton').textContent='Ⅱ';$('playButton').setAttribute('aria-label','Pause scenario replay');timer=setInterval(()=>{setTime(state.time+state.speed*.5);if(state.time>=100)pause()},200)}
function syntheticEvidence(){return `<div class="synthetic-evidence"><svg viewBox="0 0 250 100" aria-hidden="true"><path d="M9 84L53 63L84 73L123 38L154 56L186 27L240 66" fill="none" stroke="#607a54"/><path d="M67 79Q77 46 105 59T151 48Q174 46 173 70T143 84T109 90Z" fill="#d79a4d33" stroke="#edaf66" stroke-dasharray="4 4"/><circle cx="130" cy="69" r="5" fill="#efb572"/><path d="M120 69h20M130 59v20" stroke="#f6d5a2"/></svg><span>SIMULATED OBSERVATION · NO SENSOR FEED</span></div>`}
function incidentPanel(){const i=incident(),m=scene().code==='MUM';const st=stage();const labels=['Signal','Review','Verified','Request','Response','Closed'];return `<section class="incident-panel"><div class="incident-top"><div class="incident-id">${i.id}<span class="chip ${m?'blue':'orange'}">${i.severity}</span></div><h3>${i.title}</h3><p>${i.place}</p><div class="source-tags"><span class="chip muted">${m?'RECORDED RGB':'SIMULATED INPUT'}</span><span class="chip muted">${i.type}</span></div>${m?`<button class="evidence-thumb" id="incidentEvidence"><img src="/prototype/assets/mumbai-smoke.jpg" alt="Smoke imagery visible in the supplied Mumbai demo recording"><span class="play-bubble">▶</span><span class="evidence-caption">Watch original Mumbai evidence ↗</span></button><div class="evidence-label">Frame extracted from your recording. Detection accuracy is not independently validated.</div>`:syntheticEvidence()}<dl class="detail-grid"><div><dt>SOURCE</dt><dd>${i.source}</dd></div><div><dt>VERIFICATION</dt><dd>${m?'Recorded display':st>=2?'Demo verified':'Pending review'}</dd></div><div><dt>EXPOSURE</dt><dd>${i.exposure}</dd></div><div><dt>DATA STATUS</dt><dd>${m?'Historical recording':'Scenario fixture'}</dd></div></dl></div><div class="workflow"><div class="workflow-title">${m?'REFERENCE REVIEW':'OPERATOR WORKFLOW'}</div>${m?`<p class="status-note">The Mumbai recording establishes the interface shown, not the performance of a live command system.</p><button class="button primary" id="watchReference">▷ Open recorded demonstration</button><button class="button" id="goValmiki">Explore proposed Valmiki flow →</button>`:`<div class="steps">${labels.map((l,index)=>`<span class="step ${index<st?'done':index===st?'current':''}"><i>${index<st?'✓':index+1}</i>${l}</span>`).join('')}</div><button class="button primary" id="workflowAction">${['Acknowledge signal','Review & verify evidence','Request reconnaissance','Review mission request','Complete demonstration','Incident closed · view report'][st]} →</button>${scene().code==='PAT'&&st<5?'<button class="button" id="groundAction">Record ground-response notification</button>':''}<small>All actions are simulated. No flight or dispatch command is sent.</small>`}</div></section>`}
function renderCommand(){$('content').innerHTML=stats()+`<div class="command-grid">${mapMarkup()}<aside class="right-column">${incidentPanel()}<div class="mini-panel"><h3>Evidence integrity</h3><div class="mini-line"><span>Source provenance</span><b>${scene().code==='MUM'?'User recording':'Scenario fixtures'}</b></div><div class="mini-line"><span>Forecast model</span><b>Not connected</b></div><div class="mini-line"><span>Operational commands</span><b>Disabled</b></div></div></aside></div><div class="bottom-grid"><section class="list-panel"><div class="panel-head"><h3>${scene().code==='MUM'?'Recorded reference':'Scenario observations'}</h3><span class="chip muted">${scene().incidents.length} ITEMS</span></div>${scene().incidents.map(i=>`<button class="event-row" data-incident="${i.id}" style="width:100%;text-align:left;background:${i.id===state.selected?'#233329':'transparent'}"><span class="event-dot orange"></span><div class="event-main"><b>${i.title}</b><p>${i.id} · ${i.source}</p></div><span style="color:#bdcfae">↗</span></button>`).join('')}</section><section class="list-panel"><div class="panel-head"><h3>Decision trail</h3><button id="openHistory" class="text-link">View all →</button></div>${decisionRows()}</section></div>`;attachMap();document.querySelectorAll('[data-incident]').forEach(b=>b.onclick=()=>{state.selected=b.dataset.incident;render()});$('openHistory').onclick=()=>navigate('history');if($('workflowAction'))$('workflowAction').onclick=workflowAction;if($('incidentEvidence'))$('incidentEvidence').onclick=()=>openVideo(258);if($('watchReference'))$('watchReference').onclick=()=>openVideo(119);if($('goValmiki'))$('goValmiki').onclick=()=>changeScenario('valmiki');if($('groundAction'))$('groundAction').onclick=()=>{log('Ground-response notification recorded (simulation; no dispatch sent)');toast('Demo notification recorded. No emergency service contacted.');render()}}
function decisionRows(){const logs=state.logs.filter(l=>l.scenario===state.scenario).slice(0,3);if(!logs.length)return `<div class="event-row"><span class="event-dot"></span><div class="event-main"><b>${scene().code==='MUM'?'Original demo available for review':'Scenario loaded for operator review'}</b><p>${scene().code==='MUM'?'Open the recording to inspect the existing application.':'Acknowledge an observation to start the demonstration workflow.'}</p></div><time>—</time></div><div class="event-row"><span class="event-dot"></span><div class="event-main"><b>Human authority preserved</b><p>Mission requests remain separate from aircraft control.</p></div><time>—</time></div>`;return logs.map(l=>`<div class="event-row"><span class="event-dot"></span><div class="event-main"><b>${escapeHTML(l.action)}</b><p>${l.id} · demo session</p></div><time>${l.time} IST</time></div>`).join('')}
function openModal(title,eyebrow,html){pause();$('modalTitle').textContent=title;$('modalEyebrow').textContent=eyebrow;$('modalBody').innerHTML=html;if(!$('modal').open)$('modal').showModal();}
function closeModal(){const v=$('modal').querySelector('video');if(v)v.pause();$('modal').close();$('modalBody').innerHTML=''}
function openVideo(t=0){openModal('Mumbai fire & smoke demonstration','RECORDED EVIDENCE / USER-SUPPLIED',`<div class="video-frame"><video id="referenceVideo" controls playsinline preload="metadata" poster="/prototype/assets/mumbai-smoke.jpg"><source src="/prototype/assets/mumbai-demo.mp4" type="video/mp4"></video></div><p>Your original application recording, compressed for playback without audio. The interface and detection imagery are recorded; this prototype does not validate model accuracy.</p><div class="flow-list">${CHAPTERS.map(c=>`<button class="button chapter-jump" data-time="${c.t}">${Math.floor(c.t/60)}:${String(c.t%60).padStart(2,'0')} · ${c.title}</button>`).join('')}</div>`);const v=$('referenceVideo');const seek=()=>{v.currentTime=t};v.addEventListener('loadedmetadata',seek,{once:true});if(v.readyState>=1)seek();document.querySelectorAll('.chapter-jump').forEach(b=>b.onclick=()=>{v.currentTime=+b.dataset.time;v.play().catch(()=>{})})}
function workflowAction(){const s=stage();if(s===0){state.progress[incident().id]=1;log('Signal acknowledged by demonstration operator');toast('Signal acknowledged. Review evidence before verification.');render()}else if(s===1){openModal('Review the observation','HUMAN VERIFICATION / SIMULATION',`${syntheticEvidence()}<p><strong>${incident().title}</strong> is a synthetic scenario observation. In production, the operator would review geolocated imagery, sensor age, uncertainty and independent corroboration.</p><div class="check-list"><p>Source and timestamp displayed</p><p>Scenario location and exposed assets identified</p><p>Simulated evidence clearly distinguished from recorded evidence</p></div><label class="check-line"><input type="checkbox" id="verifyCheck">I have reviewed the scenario evidence and want to mark this demo incident as verified.</label><div class="modal-actions"><button class="button" id="verificationCancel">Cancel</button><button class="button primary" id="verifyConfirm" disabled>Verify demo incident</button></div>`);$('verifyCheck').onchange=e=>$('verifyConfirm').disabled=!e.target.checked;$('verificationCancel').onclick=closeModal;$('verifyConfirm').onclick=()=>{if(!$('verifyCheck').checked)return;state.progress[incident().id]=2;log('Scenario evidence reviewed; demo incident verified');closeModal();toast('Demo incident verified. Reconnaissance request is available.');render()}}else if(s===2||s===3)requestMission();else if(s===4){openModal('Complete the demonstration','SIMULATED INCIDENT CLOSURE',`<p>This closes the prototype workflow only. It does not confirm that any real fire has been contained or extinguished.</p><label class="check-line"><input id="closureCheck" type="checkbox">Mark the simulated response and incident review as complete.</label><div class="modal-actions"><button class="button primary" id="closureConfirm" disabled>Close demo incident</button></div>`);$('closureCheck').onchange=e=>$('closureConfirm').disabled=!e.target.checked;$('closureConfirm').onclick=()=>{if(!$('closureCheck').checked)return;state.progress[incident().id]=5;state.missions.filter(m=>m.incident===incident().id).forEach(m=>m.status='Completed');log('Demonstration completed; incident closed in prototype');closeModal();render();toast('Demo incident closed. Export a briefing for review.')}}else exportBriefing()}
function requestMission(){if(scene().code==='MUM'){openVideo(119);return}if(stage()<2){toast('Select and verify a scenario incident before requesting reconnaissance.');return}const i=incident();const available=scene().fleet.filter(f=>f.status==='Ready'&&!state.missions.some(m=>m.asset===f.id&&m.scenario===state.scenario&&m.status!=='Completed'));if(!available.length){toast('No unassigned surveillance aircraft in this demo. Complete an active mission first.');return}openModal('Authorise reconnaissance','MISSION REQUEST / NO AIRCRAFT CONNECTION',`<p>Request a simulated observation mission for <strong>${i.id} · ${i.title}</strong>. Payload deployment is outside this demonstration.</p><div class="form-group"><label for="missionAsset">Surveillance aircraft</label><select id="missionAsset">${available.map(f=>`<option value="${f.id}">${f.id} · ${f.battery}% battery · ${f.dock}</option>`).join('')}</select></div><div class="check-list"><p>Demo aircraft is available</p><p>Route is illustrative and has no operational clearance</p><p>Production flight controls remain with the approved mission adapter</p></div><label class="check-line"><input type="checkbox" class="mission-check">Review the operating-area and weather limits in this scenario.</label><label class="check-line"><input type="checkbox" class="mission-check">Confirm human approval for the simulated reconnaissance request.</label><div class="warning">No flight permission is granted by this screen. No command will reach an aircraft, dock or emergency service.</div><div class="modal-actions"><button id="cancelMission" class="button">Cancel</button><button id="approveMission" class="button primary" disabled>Approve demo mission →</button></div>`);document.querySelectorAll('.mission-check').forEach(c=>c.onchange=()=>{$('approveMission').disabled=![...document.querySelectorAll('.mission-check')].every(x=>x.checked)});$('cancelMission').onclick=closeModal;$('approveMission').onclick=()=>{if(![...document.querySelectorAll('.mission-check')].every(x=>x.checked))return;const asset=$('missionAsset').value;const mission={id:`DEMO-${String(state.missions.length+1).padStart(3,'0')}`,scenario:state.scenario,incident:i.id,asset,status:'Simulated response',type:'Reconnaissance',time:realClock()};state.missions.push(mission);state.progress[i.id]=4;log(`${mission.id} approved for ${asset} (simulation only)`);closeModal();render();toast(`${mission.id} created. No aircraft command sent.`)}}
function renderStreams(){const m=scene().code==='MUM';$('content').innerHTML=`<div class="source-callout"><strong>${m?'Recorded capability:':'Reference evidence from Mumbai:'}</strong> Fleet visibility, fire/smoke detection rows, route generation, zone search and image history are visible in the supplied recording. Live sensor integrations for the new pilots are proposed.</div><div class="evidence-layout"><section class="video-frame"><video id="mainVideo" controls playsinline preload="metadata" poster="/prototype/assets/mumbai-smoke.jpg"><source src="/prototype/assets/mumbai-demo.mp4" type="video/mp4"></video><div class="video-caption">MUMBAI · USER-SUPPLIED APPLICATION RECORDING<br>5 min 16 sec · compressed copy without audio · historical evidence, not a live stream</div></section><section class="content-card"><div class="eyebrow">EXISTING APPLICATION</div><h2>Walk through the evidence.</h2>${CHAPTERS.map(c=>`<button class="chapter" data-chapter="${c.t}"><time>${Math.floor(c.t/60)}:${String(c.t%60).padStart(2,'0')}</time><div><b>${c.title} ↗</b><p>${c.desc}</p></div></button>`).join('')}</section></div><div class="section-title"><h2>Proposed pilot inputs</h2><span class="chip muted">NOT CONNECTED</span></div><div class="card-grid">${[['Optical & thermal','Vendor-adapter ingestion with timestamps and camera pose. Thermal imagery is proposed here; the embedded Mumbai evidence is RGB.'],['Satellite & weather','FIRMS, authorised FSI inputs and IMD feeds, with observation time separated from receipt time.'],['Field & control room','Ranger reports, emergency intake and human verification linked to a shared incident record.']].map(([title,desc])=>`<div class="content-card"><h3>${title}</h3><p>${desc}</p><span class="chip muted" style="display:inline-block;margin-top:15px">PROPOSED INTEGRATION</span></div>`).join('')}</div>`;document.querySelectorAll('[data-chapter]').forEach(b=>b.onclick=()=>{const v=$('mainVideo');v.currentTime=+b.dataset.chapter;v.play().catch(()=>{})})}
function renderFleet(){const m=scene().code==='MUM';$('content').innerHTML=`<div class="source-callout">${m?'<strong>Recorded reference.</strong> The aircraft name below is visible in your Mumbai recording. Current aircraft telemetry, availability and dock status are not connected.':'<strong>Illustrative asset roster.</strong> These aircraft names, batteries and locations are demo fixtures. They do not represent the agreed pilot fleet allocation or operational readiness.'}</div><div class="card-grid">${scene().fleet.map((f,index)=>{const assigned=state.missions.some(m=>m.asset===f.id&&m.scenario===state.scenario&&m.status!=='Completed');return `<article class="fleet-card"><div class="drone-drawing">${icon('drone')}</div><span class="chip ${f.status==='Ready'&&!assigned?'':'muted'}">${m?'RECORDED ONLY':assigned?'ASSIGNED · DEMO':f.status.toUpperCase()+' · DEMO'}</span><h3>${f.id}</h3><p>${f.type}</p><div class="battery"><span style="width:${f.battery??0}%"></span></div><div class="metric-pair"><span>Battery</span><strong>${f.battery===null?'Not connected':f.battery+'% · simulated'}</strong></div><div class="metric-pair"><span>Base</span><strong>${f.dock}</strong></div><button class="button" data-asset="${index}">${m?'View recorded fleet':f.status==='Ready'?'Inspect mission readiness':'View payload boundary'} →</button></article>`}).join('')}</div>`;document.querySelectorAll('[data-asset]').forEach(b=>b.onclick=()=>{const f=scene().fleet[+b.dataset.asset];if(m){openVideo(42);return}openModal(f.id,'ASSET READINESS / SIMULATION',`<p>${f.type}</p><div class="metric-pair"><span>Scenario battery</span><strong>${f.battery}%</strong></div><div class="metric-pair"><span>Scenario base</span><strong>${f.dock}</strong></div>${f.status==='Ready'?'<div class="check-list"><p>Demonstration asset available</p><p>Flight envelope and radio link must be validated in production</p><p>Mission execution requires a separate authorised adapter</p></div>':'<div class="warning">Payload operations are not implemented. Production deployment requires a separate approved scenario, operating envelope and human authorisation.</div>'}<div class="modal-actions"><button class="button primary" id="fleetToCommand">Open incident workflow →</button></div>`);$('fleetToCommand').onclick=()=>{closeModal();navigate('command')}})}
function renderMissions(){const missions=state.missions.filter(m=>m.scenario===state.scenario);$('content').innerHTML=`<div class="source-callout"><strong>Mission adapter boundary.</strong> Requests here are local demonstration records. In production, the adapter would enforce aircraft health, permissions, geofencing, weather, lost-link logic and human approval.</div><div class="table-toolbar"><span class="status-note">${missions.length} demo missions in ${scene().name}</span><button id="newMission" class="button primary">+ Reconnaissance request</button></div><div class="table-wrapper"><table><thead><tr><th>MISSION</th><th>INCIDENT</th><th>AIRCRAFT</th><th>TYPE</th><th>STATUS</th><th>REVIEW</th></tr></thead><tbody>${missions.length?missions.map(m=>`<tr><td>${m.id}<small>${m.time} IST · demo session</small></td><td>${m.incident}</td><td>${m.asset}</td><td>${m.type}</td><td><span class="chip ${m.status==='Completed'?'':'blue'}">${m.status}</span></td><td><button class="text-link" data-mission="${m.id}">Open →</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty">No demonstration missions yet. Verify an incident in Command centre, then request reconnaissance.</td></tr>'}</tbody></table></div><div class="bottom-grid"><section class="content-card"><div class="eyebrow">ALREADY VISIBLE IN MUMBAI</div><h3>Detection-linked route generation</h3><p>The recorded application shows smoke/fire detections linked to generated routes, route parameters and confidence fields.</p><button class="button" id="missionReference" style="margin-top:18px">▷ Inspect original mission screen</button></section><section class="content-card"><div class="eyebrow">PROPOSED EXTENSION</div><h3>A shared incident-to-response workflow</h3><p>Link each mission to its incident, human decision, evidence and response milestones. Preserve vendor flight-safety controls.</p></section></div>`;$('newMission').onclick=()=>{if(scene().code==='MUM'){openVideo(119);return}if(stage()<2){navigate('command');toast('Acknowledge and verify the selected incident first.')}else requestMission()};$('missionReference').onclick=()=>openVideo(119);document.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>{state.selected=state.missions.find(m=>m.id===b.dataset.mission).incident;navigate('command')})}
function renderZones(){$('content').innerHTML=`<div class="source-callout"><strong>Zone search concept.</strong> Configure an illustrative patrol area. This does not define an actual flight boundary or confer airspace permission.</div><div class="zone-grid">${mapMarkup(true)}<section class="content-card"><div class="eyebrow">PATROL CONFIGURATION</div><h2>Define the next look.</h2><div class="form-group"><label for="zoneName">Zone name</label><input id="zoneName" maxlength="70" value="${scene().short} demonstration zone"></div><div class="form-group"><label for="zonePattern">Observation pattern</label><select id="zonePattern"><option>Perimeter observation</option><option>Area sweep</option><option>Point verification</option></select></div><div class="form-group"><label for="zoneRadius">Illustrative radius · <b id="radiusValue">300 m</b></label><input id="zoneRadius" type="range" min="100" max="1000" step="50" value="300"></div><div class="form-group"><label for="zonePriority">Review priority</label><select id="zonePriority"><option>Standard verification</option><option>High exposure</option><option>Follow-up observation</option></select></div><div class="warning">The scene is schematic. Surveyed boundaries, aviation permissions and a validated mission envelope must replace these fixtures before operations.</div><button id="saveZone" class="button primary" style="width:100%;margin-top:20px">Save demonstration zone</button><button id="zoneReference" class="button" style="width:100%;margin-top:8px">▷ Existing Mumbai zone search</button></section></div>`;attachMap();$('zoneRadius').oninput=e=>{$('radiusValue').textContent=e.target.value+' m';terrain.zoom=1+(+e.target.value-300)/2000;terrain.draw()};$('saveZone').onclick=()=>{const name=$('zoneName').value.trim();if(!name){toast('Enter a zone name.');$('zoneName').focus();return}log(`Demo zone saved: ${name}; ${$('zonePattern').value}; radius ${$('zoneRadius').value} m`);toast('Demonstration zone recorded in the decision history. No flight boundary applied.')};$('zoneReference').onclick=()=>openVideo(185)}
function renderHistory(){const rows=[...state.logs.filter(l=>l.scenario===state.scenario).map(l=>({id:l.id,type:'Demo action',text:l.action,source:'Prototype session',time:l.time+' IST'})),...scene().incidents.map(i=>({id:i.id,type:scene().code==='MUM'?'Recorded reference':'Scenario observation',text:i.title,source:i.source,time:scene().code==='MUM'?'Recording':'14:00 · scenario'}))];$('content').innerHTML=`<div class="table-toolbar"><input id="historySearch" class="search-input" placeholder="Search incident, source or action…" aria-label="Search detection history" value="${escapeHTML(state.filter)}"><select id="historyType" class="select" aria-label="History type"><option value="all">All records</option value="Demo action" ${state.typeFilter==='Demo action'?'selected':''}>Demo actions</option><option value="Scenario observation" ${state.typeFilter==='Scenario observation'?'selected':''}>Scenario observations</option><option value="Recorded reference" ${state.typeFilter==='Recorded reference'?'selected':''}>Recorded references</option></select><button id="downloadHistory" class="button">Download JSON ↓</button></div><div class="table-wrapper"><table><thead><tr><th>INCIDENT</th><th>OBSERVATION / ACTION</th><th>PROVENANCE</th><th>TIME</th><th>REVIEW</th></tr></thead><tbody id="historyRows"></tbody></table></div><div class="legend-line">Demo action times are your session time in IST. Scenario observation times are invented. The recording is historical and is not a live feed.</div>`;const fill=()=>{const filtered=rows.filter(r=>(state.typeFilter==='all'||r.type===state.typeFilter)&&[r.id,r.text,r.source].join(' ').toLowerCase().includes(state.filter.toLowerCase()));$('historyRows').innerHTML=filtered.length?filtered.map(r=>`<tr><td>${r.id}</td><td>${escapeHTML(r.text)}<small>${r.type}</small></td><td>${escapeHTML(r.source)}</td><td>${r.time}</td><td><button class="text-link" data-history="${r.id}">Open →</button></td></tr>`).join(''):'<tr><td colspan="5" class="empty">No records match these filters.</td></tr>';document.querySelectorAll('[data-history]').forEach(b=>b.onclick=()=>{state.selected=b.dataset.history;navigate('command')})};fill();$('historySearch').oninput=e=>{state.filter=e.target.value;fill()};$('historyType').onchange=e=>{state.typeFilter=e.target.value;fill()};$('downloadHistory').onclick=()=>downloadJSON({prototype:true,scenario:state.scenario,records:rows},'ABHAI_'+scene().code+'_Demo_History.json')}
function renderSafety(){$('content').innerHTML=`<div class="source-callout"><strong>Demonstration boundary.</strong> This prototype has no flight-control, government dispatch, live satellite, weather or sensor connection. Its controls show the proposed approval flow.</div><div class="architecture-grid">${[['Human authority','An operator reviews evidence and approves a reconnaissance request. Payload deployment requires a separate, approved workflow.'],['Flight safety','Aircraft health, weather limits, approved airspace, geofencing, communications and lost-link behaviour belong in the mission adapter and aircraft controls.'],['Source integrity','Display observed time, received time, source, location uncertainty and last verification. Do not treat repeated satellite-derived alerts as independent confirmation.'],['Degraded connectivity','A production edge gateway buffers alerts and evidence. Stale data must remain visibly stale; an offline feed does not mean there is no fire.'],['Government data control','Use the approved hosting and backup environment, role-based access, encryption, retention limits and auditable support access.'],['Public information','Publish only approved, filtered records to a separate public view. Exclude operational video, personal data and sensitive wildlife locations.']].map(([t,d],i)=>`<section class="architecture-box"><span class="number">0${i+1} / PROPOSED CONTROL</span><h3>${t}</h3><p>${d}</p></section>`).join('')}</div><div class="content-card wide-card"><h3>Reset the demonstration</h3><p>Clear this browser’s demonstration missions and decision trail. The source recording and all scenario fixtures remain available.</p><button class="button" id="resetDemo" style="margin-top:18px">Reset local demo state</button></div>`;$('resetDemo').onclick=()=>{openModal('Reset demonstration state?','LOCAL BROWSER DATA',`<p>This removes the demo actions and missions created in this browser. It does not change your actual ABHAI application or the Mumbai recording.</p><div class="modal-actions"><button class="button" id="cancelReset">Keep my demo</button><button class="button primary" id="confirmReset">Reset demo</button></div>`);$('cancelReset').onclick=closeModal;$('confirmReset').onclick=()=>{state.logs=[];state.missions=[];state.progress={};save();closeModal();render();toast('Demonstration reset.')}}}
function renderArchitecture(){$('content').innerHTML=`<div class="architecture-flow">Recorded Mumbai capability <span>→</span> Shared incident service <span>→</span> 2D / 3D command view <span>→</span> Authorised mission adapter <span>→</span> Evidence & evaluation</div><div class="architecture-grid">${[
 ['01','Inputs & provenance','Vendor telemetry, optical/thermal observations, authorised satellite/weather feeds, and departmental reports. Preserve source and acquisition time.','INTEGRATION'],
 ['02','Incident correlation','Link observations by location and time. Preserve uncertainty, source lineage and operator decisions. Keep confidence separate from severity.','ABHAI CORE'],
 ['03','Geospatial command','Production candidate: React + CesiumJS, with a 2D option. PostGIS stores geometry; imagery and clips remain in authenticated object storage.','PROPOSED STACK'],
 ['04','Human response workflow','Acknowledge → verify → request → approve → record. Existing emergency dispatch continues without waiting for aerial verification.','ABHAI CORE'],
 ['05','Mission & edge adapters','Integrate MENAPS / Indrones interfaces. Keep aircraft safety local; buffer essential evidence during poor connectivity.','PARTNER INTERFACES'],
 ['06','Governance & evidence','Approved hosting, role permissions, audit records, retention rules and incident replay. Public publishing remains a separate approval process.','GOVERNMENT CONTROL']
 ].map(([n,t,d,tag])=>`<section class="architecture-box"><span class="number">${n}</span><h3>${t}</h3><p>${d}</p><span class="chip muted">${tag}</span></section>`).join('')}</div><div class="section-title"><h2>What exists, what this prototype adds</h2><button id="architectureEvidence" class="text-link">Inspect Mumbai recording →</button></div><div class="table-wrapper"><table><thead><tr><th>CAPABILITY</th><th>EVIDENCE / CURRENT BOUNDARY</th><th>NEXT IMPLEMENTATION STEP</th></tr></thead><tbody>${[
 ['Fleet map & telemetry UI','Visible in the supplied Mumbai recording','Obtain documented vendor data interfaces and sample payloads.'],
 ['Smoke/fire detections & route UI','Visible in the supplied Mumbai recording; accuracy not independently assessed','Preserve observation metadata and link to a common incident ID.'],
 ['Zone search & detection history','Visible in the supplied Mumbai recording','Connect approved GIS boundaries, searchable records and audit events.'],
 ['3D view & scenario replay','Working illustrative visualisation in this prototype','Replace schematic terrain/buildings with approved spatial data.'],
 ['Human-approved incident workflow','Working browser-local simulation in this prototype','Implement authenticated server workflows and mission adapters.'],
 ['Spread prediction & smoke modelling','Not implemented or claimed','Select a specialist model, gather fuel/weather inputs and validate locally.']
 ].map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="bottom-grid"><section class="content-card"><div class="eyebrow">MINIMUM INCIDENT CONTRACT</div><h3>One ID across the response.</h3><p>Incident ID · observations · source lineage · geometry + uncertainty · observed/received timestamps · status · responsible authority · evidence references · approved missions · immutable audit events.</p><p>The aircraft position and the observed hotspot position must be separate fields.</p></section><section class="content-card"><div class="eyebrow">FIRST ACCEPTANCE DRILL</div><h3>Signal → evidence → decision → replay.</h3><p>Inject a known observation, verify its correct map placement, approve a simulated request, disconnect a feed, reconnect it, and reconstruct the full incident without losing source timestamps or decisions.</p></section></div><div class="content-card"><div class="eyebrow">TECHNICAL HANDOFF</div><h3>Prototype implementation</h3><p>This release is a dependency-free static web app. Its interactive scene uses a custom Canvas renderer with procedural terrain; it does not use real elevation tiles or a fire-spread model. All synthetic fixtures are isolated in <code>data.js</code>. Workflow records persist only in this browser.</p><p>Production migration: retain the interface and incident semantics, replace the scene renderer with validated GIS data and replace local state with secured services. Source code is available in the download below.</p><div class="flow-list"><span>Frontend: HTML / CSS / JavaScript</span><span>Storage: local browser only</span><span>Recorded video: Mumbai reference</span><span>Live integrations: none</span></div></div>`;$('architectureEvidence').onclick=()=>openVideo(119)}
function exportBriefing(){const s=scene(),i=incident(),logs=state.logs.filter(l=>l.scenario===state.scenario);const data={title:'ABHAI FireDome — Demonstration briefing',generatedAt:new Date().toISOString(),scenario:s.name,prototype:true,geography:'Illustrative; not survey data',liveConnections:false,incident:{id:i.id,title:i.title,status:s.code==='MUM'?'Recorded reference':['Detected','Under review','Demo verified','Mission requested','Simulated response','Demo closed'][stage()]},missions:state.missions.filter(m=>m.scenario===state.scenario),audit:logs};openModal('Demonstration briefing','EXPORT / OFFICIALS & TECHNICAL REVIEW',`<article class="report-sheet"><div class="eyebrow" style="color:#426e39">ABHAI FIREDOME · PROTOTYPE</div><h2>${s.name}</h2><p>Prepared ${new Date().toLocaleString('en-IN',{timeZone:'Asia/Kolkata'})} IST</p><p><strong>Purpose:</strong> demonstrate incident intelligence, recorded evidence review, human-approved reconnaissance and response replay.</p><table><tbody><tr><th>SELECTED INCIDENT</th><td>${i.id} · ${i.title}</td></tr><tr><th>WORKFLOW STATE</th><td>${data.incident.status}</td></tr><tr><th>LIVE CONNECTIONS</th><td>None. No commands sent.</td></tr><tr><th>GEOGRAPHY</th><td>Illustrative, not survey data.</td></tr><tr><th>RECORDED EVIDENCE</th><td>Supplied Mumbai application recording.</td></tr><tr><th>DEMO MISSIONS</th><td>${data.missions.length}</td></tr></tbody></table><h3>Decision trail</h3>${logs.length?logs.map(l=>`<p>${l.time} IST — ${escapeHTML(l.action)}</p>`).join(''):'<p>No operator actions recorded in this scenario.</p>'}<h3>Implementation decisions</h3><p>Confirm partner interfaces, approved GIS layers, data ownership and hosting, operator roles, mission authorisation boundaries and pilot acceptance metrics.</p><p>Simulated behaviour and recorded interface evidence do not establish operational readiness, detection accuracy or prediction performance.</p></article><div class="modal-actions"><button id="briefJSON" class="button">Download JSON</button><button id="briefPrint" class="button primary">Print / save PDF</button></div>`);$('briefJSON').onclick=()=>downloadJSON(data,'ABHAI_'+s.code+'_Demo_Briefing.json');$('briefPrint').onclick=()=>window.print()}
function downloadJSON(data,name){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Demonstration data exported.')}
function showScope(){openModal('What this prototype demonstrates','ABHAI FIREDOME / CONCEPT RELEASE 01',`<h3>Grounded in the existing application</h3><p>Your Mumbai recording visibly includes a fleet map, smoke/fire detection rows, generated mission routes, zone search, and detection history with RGB imagery. The recording is embedded for direct review.</p><h3>Proposed capabilities you can interact with</h3><p>Valmiki and Patna scenario workspaces, rotatable schematic scenes, signal selection, layer controls, replay, human verification, simulated mission approval, decision history and briefing export.</p><h3>Clear limits</h3><p>No live aircraft, cameras, satellite/weather feeds or emergency services are connected. Terrain, buildings, aircraft, wind and incident progression in the pilot scenes are illustrative fixtures. This is not a validated fire forecast or a surveyed digital twin.</p><h3>For the demonstration</h3><p>Use Guided demo for a six-step presentation. Start with the Mumbai recording, move into Valmiki, demonstrate an approval, switch to Patna, and finish with the CTO architecture view.</p><p>Demo records persist in this browser. Reset them from Rules & safety before a new session.</p>`)}
function renderTour(){const panel=$('tourPanel');if(state.tour<0){panel.hidden=true;return}const t=TOUR[state.tour];panel.hidden=false;panel.innerHTML=`<span class="tour-number">0${state.tour+1}</span><div><h3>${t.title}</h3><p>${t.text}</p></div><div class="tour-actions"><button id="tourPrev" class="button" ${state.tour===0?'disabled':''}>Back</button><button id="tourNext" class="button primary">${state.tour===TOUR.length-1?'Finish':'Next'} →</button><button id="tourClose" class="icon-button" aria-label="End guided demo">×</button></div>`;$('tourPrev').onclick=()=>goTour(state.tour-1);$('tourNext').onclick=()=>{if(state.tour===TOUR.length-1){state.tour=-1;renderTour();toast('Demonstration complete. Export a briefing for the discussion.')}else goTour(state.tour+1)};$('tourClose').onclick=()=>{state.tour=-1;renderTour()}}
function goTour(index){pause();state.tour=index;const t=TOUR[index];state.scenario=t.scenario;state.selected=scene().incidents[0].id;state.page=t.page;state.time=t.replay?0:12;render();if(t.chapter&&$('mainVideo')){const v=$('mainVideo');v.addEventListener('loadedmetadata',()=>{v.currentTime=t.chapter},{once:true})}window.scrollTo({top:0,behavior:'smooth'})}
$('closeModal').onclick=closeModal;$('modal').addEventListener('cancel',()=>{const v=$('modal').querySelector('video');if(v)v.pause()});$('modal').addEventListener('click',e=>{if(e.target===$('modal')){const r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
$('evidenceButton').onclick=()=>openVideo(0);$('briefButton').onclick=exportBriefing;$('scopeButton').onclick=showScope;$('tourButton').onclick=()=>goTour(0);$('presentButton').onclick=()=>{document.body.classList.toggle('presentation');$('presentButton').setAttribute('aria-pressed',document.body.classList.contains('presentation'));if(terrain)setTimeout(()=>terrain.resize(),40)};
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(NAV_ITEMS.some(n=>n[0]===p)){state.page=p;render()}});
const initialPage=location.hash.slice(1);if(NAV_ITEMS.some(n=>n[0]===initialPage))state.page=initialPage;
render();
